svg.script:
(function () {
  function calibrate() {
    try {
      var svg = document.currentScript ? document.currentScript.ownerSVGElement : document.rootElement;
      if (!svg) return;
      var text = svg.querySelector('text');
      var tittle = svg.querySelector('#tittle');
      if (!text || !tittle) return;
      // Use getExtentOfChar to find the first "i" (index 3 in "Decisive").
      var firstI = text.getExtentOfChar(3);
      var secondI = text.getExtentOfChar(5);
      var cx = firstI.x + firstI.width / 2;
      // Tittle center y: use cap-height offset. Second i's extent top = cap-to-tittle top.
      // We paint the orange at same y as would cover second i's tittle.
      var cy = secondI.y + (secondI.height * 0.09); // approximates tittle center
      tittle.setAttribute('cx', cx);
      tittle.setAttribute('cy', cy);
    } catch (e) { /* fall back to hardcoded */ }
  }
  if (document.readyState === 'complete') calibrate();
  else window.addEventListener('load', calibrate);
})();
